3	import java.util.Locale;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	
9	/**
10	 * Assigns a new owner's {@code customerCode}, formatted {@code <CITY3>-<LAST3>-<NNNN>} where CITY3 is
11	 * the upper-cased first three letters of the city, LAST3 the upper-cased first three letters of the
12	 * last name and NNNN a per-city 4-digit zero-padded sequence equal to one more than the owners already
13	 * in that city (e.g. {@code SYD-SMI-0007}). Runs after {@link BuildOwner} maps the request and before
14	 * {@link SaveOwner} persists it, so the count reflects the owners already stored, not the one being
15	 * created.
16	 */
17	public class AssignOwnerCustomerCode {
18	
19	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
20	        String city = owner.getCity();
21	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
22	        String lastName = owner.getLastName();
23	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
24	        int sequence = (int) ownerRepository.findAll().stream()
25	                .filter(o -> city.equalsIgnoreCase(o.getCity()))
26	                .count() + 1;
27	        owner.setCustomerCode(String.format("%s-%s-%04d", city3, last3, sequence));
28	    }
29	}
